import {mountMusic} from './music.mjs';
import{dailyRitual}from'./ritual.mjs';
import{uploadCommunityMedia,discardCommunityMedia}from'./media-client.mjs';
import{sessionIdentity,pendingPublication,scopedStore,profileMatches,assertScope}from'./session-state.mjs';
import{mediaMetadata}from'./media-rules.mjs';
import{icon}from'./icons.mjs';
import{esc,UUID,TOPICS,safeUrl,initials,age,mediaItems,receipt,friendlyError}from'./view-model.mjs';
const C=window.ZoiCore,root=document.querySelector('#agora');
const modes=[['for_you','For you','spark'],['following','Following','people'],['watch','Watch','play'],['questions','Ask Greeks','chat'],['near_me','Near me','pin'],['saved','Saved','save']];
const state={mode:'for_you',topic:null,query:'',posts:[],asOf:null,next:null,me:null,rules:[],loading:false,generation:0,profile:null,account:sessionIdentity(C),epoch:0,postView:null};
const rpc=async(name,args={},auth='require')=>{const account=state.account,epoch=state.epoch;assertScope(account,sessionIdentity(C));const value=await C.api.rpc(name,args,{auth});assertScope(account,sessionIdentity(C));if(epoch!==state.epoch)throw Error('session_changed');return receipt(value);};
const avatar=(p,button=true)=>`<${button?'button':'span'} class="ag-avatar" ${button?`data-profile="${esc(p?.id||'')}" aria-label="Open ${esc(p?.display_name||'Community member')} profile"`:''}>${safeUrl(p?.avatar_url)?`<img src="${esc(safeUrl(p.avatar_url))}" alt="" loading="lazy" referrerpolicy="no-referrer">`:esc(initials(p?.display_name))}</${button?'button':'span'}>`;
root.innerHTML=`<header class="ag-top"><div class="ag-top-inner"><a class="ag-logo" href="/"><span>Ζ</span>zoi<small>The Greek world, together.</small></a><form class="ag-search" data-search>${icon('search')}<input aria-label="Search community posts" name="query" placeholder="Find a conversation, an idea, your people" maxlength="100"></form><div class="ag-top-actions"><button class="ag-icon" data-notifications aria-label="Notifications">${icon('bell')}</button><button class="ag-icon" id="themeBtn" aria-label="Switch theme">◐</button><button class="ag-primary" data-account>Join the conversation</button></div></div></header><div class="ag-layout"><aside class="ag-left" aria-label="Community navigation">${modes.map(([mode,label,symbol])=>`<button class="ag-nav" data-mode="${mode}" aria-current="${mode===state.mode}">${icon(symbol)}${label}</button>`).join('')}<div class="ag-divider"></div><p class="ag-label">Your Greek world</p><a class="ag-nav" href="/explore/">${icon('globe')}Discover</a><a class="ag-nav" href="/tickets/">${icon('play')}Events & tickets</a><a class="ag-nav" href="/trips/">${icon('pin')}Plan your Greece</a><a class="ag-nav" href="/shop/">${icon('save')}Buy Greek</a><button class="ag-primary" data-compose="moment">${icon('plus')}Share a moment</button></aside><main class="ag-main" id="feed"><div class="ag-heading"><div><h1>Agora<span aria-hidden="true" style="color:var(--acc)">.</span></h1><p>Your people. Your stories. Wherever you are.</p></div><button class="ag-icon" data-preferences aria-label="Personalize your feed">${icon('settings')}</button></div><div class="ag-tabs" aria-label="Choose feed">${modes.slice(0,5).map(([mode,label])=>`<button data-mode="${mode}" aria-current="${mode===state.mode}">${label}</button>`).join('')}<button data-mode="latest" aria-current="false">Latest</button></div><section class="ag-composer" aria-label="Create a post"><div class="ag-compose-line"><span data-own-avatar>${avatar(null,false)}</span><button class="ag-invite" data-compose="moment">What’s happening in your world?</button></div><div class="ag-compose-tools"><button data-compose="moment">${icon('image')}Photo / video</button><button data-compose="question">${icon('chat')}Ask Greeks</button><button data-compose="recommendation">${icon('pin')}Recommend</button></div></section><div class="ag-topics" aria-label="Filter by topic"><button class="ag-chip" data-topic="" aria-pressed="true">All interests</button>${TOPICS.map(t=>`<button class="ag-chip" data-topic="${t}" aria-pressed="false">${t}</button>`).join('')}</div><p class="ag-status" role="status" aria-live="polite" data-status></p><div data-feed aria-busy="true"><p class="ag-loading">Finding the latest conversations…</p></div><button class="ag-subtle ag-load-more" data-more hidden>More conversations</button><details class="ag-rules"><summary>How your feed works</summary><div data-rules></div></details></main><aside class="ag-right"><section class="ag-world"><p class="ag-label">There’s a little Greece everywhere</p><h2>One world.<br>All of us.</h2><p>Find the people and places that make wherever you are feel like home.</p><a href="/explore/map/">Explore your Greek world ${icon('arrow')}</a></section><section class="ag-panel"><h2>Make this your Agora</h2><p>Choose your interests and hometown to shape the conversations you discover.</p><button class="ag-subtle" data-preferences>Personalize your feed</button></section><section class="ag-panel" data-discovery><h2>Discover Greek businesses</h2><p>Explore the people behind the places.</p><a href="/explore/">Open Discover →</a></section><section class="ag-panel" data-ritual></section><div class="ag-note">A place to share, ask and belong.<br><a href="/business/">Build your business on Zoi</a></div></aside></div><nav class="ag-bottom" aria-label="Mobile navigation"><button data-mode="for_you" aria-current="true">${icon('home')}Home</button><button data-mode="watch">${icon('play')}Watch</button><button class="ag-new" data-compose="moment" aria-label="Create a post">${icon('plus')}</button><button data-mode="questions">${icon('chat')}Ask</button><button data-account>${icon('people')}You</button></nav><dialog class="ag-dialog" data-dialog aria-labelledby="ag-dialog-title"><div class="ag-dialog-head"><h2 id="ag-dialog-title" data-dialog-title></h2><button class="ag-icon" data-close aria-label="Close">${icon('close')}</button></div><div class="ag-dialog-body" data-dialog-body></div></dialog>`;
const $=s=>root.querySelector(s),dialog=$('[data-dialog]'),status=message=>$('[data-status]').textContent=message;
let draft={body:'',intent:'moment',topics:[],files:[],pending:null,busy:false},dialogVersion=0,feedObserver=null;const mutations=new Set(),commentRequests=new Map();let profileDraft=null,notificationView=null;
const store=(kind,value)=>scopedStore(sessionStorage,state.me?.profile?.id,kind,value);
function checkAccount(){const account=sessionIdentity(C);if(account===state.account)return false;state.account=account;state.epoch++;state.generation++;state.me=null;state.posts=[];state.next=null;state.profile=null;state.postView=null;state.mode='for_you';commentRequests.clear();draft.files.forEach(m=>URL.revokeObjectURL(m.preview));if(profileDraft?.file)URL.revokeObjectURL(profileDraft.file.preview);draft={body:'',intent:'moment',topics:[],files:[],pending:null,busy:false};profileDraft=null;close();renderFeed();$('[data-account]').textContent='Join the conversation';$('[data-own-avatar]').innerHTML=avatar(null,false);return true;}
async function accountReady(){if(checkAccount())await loadMe();if(!state.me)throw Error('account_unavailable');return {account:state.account,epoch:state.epoch};}
function checkScope(scope){assertScope(scope.account,sessionIdentity(C));if(scope.epoch!==state.epoch)throw Error('session_changed');}
function open(title,html){dialogVersion++;$('[data-dialog-title]').textContent=title;$('[data-dialog-body]').innerHTML=html;if(!dialog.open)dialog.showModal();return dialogVersion;}
function close(){dialogVersion++;dialog.querySelectorAll('video').forEach(v=>v.pause());dialog.close();}
function needAuth(){if(checkAccount()){loadMe().then(()=>loadFeed()).catch(()=>status('Your account could not be loaded. Retry after signing in.'));return false;}if(C.auth.isSignedIn()&&state.me)return true;if(C.auth.isSignedIn()){loadMe().then(()=>status('Account loaded. Please retry your action.')).catch(()=>status('Your account could not be loaded. Try again.'));return false;}signIn();return false;}
async function action(key,fn){if(mutations.has(key))return;mutations.add(key);const epoch=state.epoch;try{await fn();}catch(e){if(epoch!==state.epoch||state.account!==sessionIdentity(C)){checkAccount();loadMe().then(()=>loadFeed()).catch(()=>{});return;}const target=dialog.open?dialog.querySelector('[data-form-status]'):null;if(target)target.textContent=draft.pending&&dialog.querySelector('[data-publish]')?'Publication is not confirmed. Retry the same publication here; your request has been kept.':friendlyError(e);else status(friendlyError(e));}finally{mutations.delete(key);}}
function signIn(){open('Welcome to your Agora',`<p>Sign in to follow people, save conversations and join in.</p><form data-signin><label>Email<input name="email" type="email" autocomplete="email" required></label><button class="ag-primary">Send sign-in code</button></form><p role="status" data-form-status></p>`);}
function storePending(value){return store('pending',value);}
async function loadMe(){if(!C.auth.isSignedIn())await C.auth.ensureFresh();checkAccount();const epoch=state.epoch;const me=C.auth.isSignedIn()?await rpc('community_me'):null;if(epoch!==state.epoch)return;if(me&&!UUID.test(me.profile?.id||''))throw Error('account_unconfirmed');state.me=me;if(me&&!draft.pending){try{const saved=store('pending');if(pendingPublication(saved)){draft={body:saved.p_body,intent:saved.p_context.intent,topics:saved.p_context.topics,files:[],pending:saved,busy:false};status('A previous publication is awaiting confirmation. Open the composer to retry the same request.');}}catch{status('Browser draft storage is unavailable. Publication will wait until it can preserve a retry receipt.');}}$('[data-account]').textContent=me?'Your profile':'Join the conversation';$('[data-own-avatar]').innerHTML=avatar(me?.profile,false);}
function postCard(p){const media=mediaItems(p.media),name=p.author?.display_name||'Community member';return `<article class="ag-post" data-post="${esc(p.id)}"><header class="ag-post-head">${avatar(p.author)}<div><button class="ag-author" data-profile="${esc(p.author?.id)}">${esc(name)}</button><div class="ag-meta"><time datetime="${esc(p.created_at)}">${esc(age(p.created_at))}</time>${p.author?.city?` · ${esc(p.author.city)}`:''}${p.author?.handle?` · @${esc(p.author.handle)}`:''}</div></div><button class="ag-icon" data-post-menu="${esc(p.id)}" aria-label="Post options">${icon('dots')}</button></header>${p.intent==='question'?`<div class="ag-post-kicker">${icon('chat')}Ask the diaspora${p.accepted_comment_id?' · Useful answer chosen':''}</div>`:''}<p class="ag-body">${esc(p.body)}</p>${p.topics?.length?`<div class="ag-post-tags">${p.topics.map(t=>`<span>#${esc(t)}</span>`).join('')}</div>`:''}${media.length?`<div class="ag-media">${media.map((m,i)=>m.type==='video'?`<video src="${esc(safeUrl(m.url))}" ${safeUrl(m.poster_url)?`poster="${esc(safeUrl(m.poster_url))}"`:''} controls playsinline muted preload="none" aria-label="${esc(m.alt||'Community video')}"></video>`:`<button data-photo="${esc(p.id)}" data-index="${i}" aria-label="Open ${esc(m.alt||'photo')}"><img src="${esc(safeUrl(m.url))}" alt="${esc(m.alt||'Photo shared by '+name)}" loading="lazy" decoding="async" referrerpolicy="no-referrer"></button>`).join('')}</div>`:''}<div class="ag-post-actions"><button data-like="${esc(p.id)}" aria-pressed="${!!p.liked}" aria-label="${p.liked?'Unlike':'Like'} post">${icon('heart')}<span>${Number(p.likes)||0}</span></button><button data-comments="${esc(p.id)}" aria-label="Open replies">${icon('chat')}<span>${Number(p.comments)||0}</span></button><button data-share="${esc(p.id)}" aria-label="Share post">${icon('share')}</button><button data-save="${esc(p.id)}" aria-pressed="${!!p.saved}" aria-label="${p.saved?'Unsave':'Save'} post">${icon('save')}</button></div>${p.ranking_reasons?.length?`<div class="ag-reason">${esc(p.ranking_reasons.join(' · '))}</div>`:''}</article>`;}
function observeVideo(){feedObserver?.disconnect();feedObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)entry.target.pause();}},{threshold:.6});root.querySelectorAll('video').forEach(video=>{feedObserver.observe(video);video.addEventListener('play',()=>root.querySelectorAll('video').forEach(other=>{if(other!==video)other.pause();}));});}
function renderFeed(){const labels={following:['Your people will appear here','Follow someone’s public profile to keep up with what they share.'],watch:['The next story could be yours','Videos shared by the community will appear here.'],questions:['What would you like to know?','Ask the diaspora for local knowledge, ideas and recommendations.'],saved:['Keep the good conversations','Save a post and find it here whenever you need it.'],near_me:['Bring your Greek world closer','Choose your city in feed preferences to discover local conversations.']};const [title,body]=labels[state.mode]||['Start something worth sharing','Share a moment, ask a question or introduce yourself to Greeks everywhere.'];$('[data-feed]').innerHTML=state.posts.map(postCard).join('')||`<section class="ag-empty">${icon(state.mode==='watch'?'play':'chat')}<h2>${title}</h2><p>${body}</p><button class="ag-primary" ${state.mode==='near_me'?'data-preferences':'data-compose="question"'}>${state.mode==='near_me'?'Choose your city':'Start a conversation'}</button></section>`;$('[data-more]').hidden=state.next==null;$('[data-rules]').innerHTML=state.rules.map(r=>`<p>${esc(r)}</p>`).join('');observeVideo();}
async function loadFeed(more=false){if(state.postView&&!more)return openPost(state.postView);const generation=++state.generation;state.loading=true;$('[data-feed]').setAttribute('aria-busy','true');$('[data-more]').disabled=true;try{const r=await rpc('community_feed',{p_mode:state.mode,p_limit:20,p_offset:more?state.next||0:0,p_as_of:more?state.asOf:null,p_profile:state.profile,p_topic:state.topic,p_query:state.query},'prefer');if(generation!==state.generation)return;if(!Array.isArray(r.posts)||(r.next_offset!==null&&!Number.isInteger(r.next_offset)))throw Error('feed_unconfirmed');state.posts=more?[...state.posts,...r.posts.filter(p=>!state.posts.some(x=>x.id===p.id))]:r.posts;state.asOf=r.as_of;state.next=r.next_offset;state.rules=r.ranking_rules||[];renderFeed();status('');}catch(e){if(generation!==state.generation)return;status('Community feed failed to load. Please retry.');if(!more)$('[data-feed]').innerHTML=`<section class="ag-empty"><h2>Let’s reconnect</h2><p>The latest conversations aren’t available right now.</p><button class="ag-primary" data-retry>Retry feed</button></section>`;}finally{if(generation===state.generation){state.loading=false;$('[data-feed]').setAttribute('aria-busy','false');$('[data-more]').disabled=false;}}}
function switchMode(mode){state.postView=null;if(['following','saved','near_me'].includes(mode)&&!needAuth())return;state.mode=mode;state.profile=null;root.querySelectorAll('[data-mode]').forEach(n=>n.setAttribute('aria-current',String(n.dataset.mode===mode)));loadFeed();}
function replyCard(c,post){return `<article class="ag-reply" data-reply-id="${esc(c.id)}">${avatar(c.author)}<div class="ag-reply-body"><button class="ag-author" data-profile="${esc(c.author?.id)}">${esc(c.author?.display_name||'Community member')}</button><small> · ${esc(age(c.created_at))}</small><p>${esc(c.body)}</p>${c.accepted?'<small>✓ Chosen as useful by the person who asked</small>':''}${post.mine&&post.intent==='question'&&!c.mine?`<button class="ag-subtle" data-accept="${esc(c.id)}" data-question="${post.id}">${c.accepted?'Clear useful answer':'Mark as useful'}</button>`:''}</div></article>`;}
function pendingReply(id){try{const p=state.me&&store('reply_'+id);return UUID.test(p?.p_request||'')&&p.p_post===id&&typeof p.p_body==='string'?p:null;}catch{return null;}}
async function comments(id){const post=state.posts.find(p=>p.id===id);if(!post)return;const version=open('The conversation','<p class="ag-loading">Loading replies…</p>');const r=await rpc('community_comments',{p_post:id},'prefer');if(version!==dialogVersion)return;if(!Array.isArray(r.comments))throw Error('comments_unconfirmed');const pending=pendingReply(id);$('[data-dialog-body]').innerHTML=`<p class="ag-note">${esc(post.body)}</p><div data-replies>${r.comments.map(c=>replyCard(c,post)).join('')||'<p class="ag-note">Be the first to reply.</p>'}</div>${r.next_offset!=null?`<button class="ag-subtle" data-more-comments="${id}" data-offset="${r.next_offset}">More replies</button>`:''}<form data-comment="${id}"><label>Your reply<textarea name="body" maxlength="500" required placeholder="Add something helpful…" ${pending?'readonly':''}>${esc(pending?.p_body||'')}</textarea></label><button class="ag-primary">${pending?'Retry the same reply':'Reply'}</button></form><p role="status" data-form-status>${pending?'A previous reply is awaiting confirmation. Retry preserves its original request.':''}</p>`;}
async function showProfile(id){if(!UUID.test(id||''))return;const version=open('Community profile','<p>Opening profile…</p>');const r=await rpc('community_profile_get',{p_profile:id,p_handle:null},'prefer');if(version!==dialogVersion)return;const p=r.profile;if(!p){$('[data-dialog-body]').innerHTML='<p>This public profile is not available.</p>';return;}$('[data-dialog-body]').innerHTML=`${avatar(p,false)}<h2>${esc(p.display_name)}</h2><p class="ag-note">${p.handle?'@'+esc(p.handle):''}${p.city?' · '+esc(p.city):''}</p><p>${esc(p.bio)}</p><p>${Number(p.follower_count)||0} followers · ${Number(p.following_count)||0} following · ${Number(p.post_count)||0} posts</p><div class="ag-topics">${(p.interests||[]).map(t=>`<span class="ag-chip">${esc(t)}</span>`).join('')}</div>${p.mine?'<button class="ag-primary" data-edit-profile>Edit your profile</button>':`<button class="ag-primary" data-follow="${p.id}" data-following="${!!p.followed}">${p.followed?'Following · unfollow':'Follow'}</button>`}<button class="ag-subtle" data-profile-feed="${p.id}">View posts</button>${!p.mine?`<button class="ag-subtle" data-mute="${p.id}">Mute</button><button class="ag-subtle" data-block="${p.id}">Block</button>`:''}<p role="status" data-form-status></p>`;}
function topicChecks(selected=[]){return `<div class="ag-topics" style="flex-wrap:wrap">${TOPICS.map(t=>`<label class="ag-chip"><input type="checkbox" name="topics" value="${t}" ${selected.includes(t)?'checked':''}>${t}</label>`).join('')}</div>`;}
function preferences(){if(!needAuth())return;const p=state.me?.preferences||{};open('Make this your Agora',`<form data-preferences-form><p class="ag-note">These choices are private. Your public profile has its own location and interests.</p><h3>Your interests</h3>${topicChecks(p.topics)}<label>City<input name="city" maxlength="120" value="${esc(p.city)}"></label><label>Country<input name="country" maxlength="120" value="${esc(p.country)}"></label><label><input type="checkbox" name="locality" ${p.locality_enabled?'checked':''}>Use this location for Near me</label><button class="ag-primary">Save preferences</button></form><p role="status" data-form-status></p>${state.me?.blocked?.length?'<h3>Blocked accounts</h3>'+state.me.blocked.map(p=>`<p>${esc(p.display_name)} <button class="ag-subtle" data-unblock="${p.id}">Unblock</button></p>`).join(''):''}${state.me?.muted?.length?'<h3>Muted accounts</h3>'+state.me.muted.map(p=>`<p>${esc(p.display_name)} <button class="ag-subtle" data-unmute="${p.id}">Unmute</button></p>`).join(''):''}`);}
function profileValues(form){const f=new FormData(form);return {handle:String(f.get('handle')||''),display_name:String(f.get('display_name')||''),bio:String(f.get('bio')||''),city:String(f.get('city')||''),country:String(f.get('country')||''),interests:f.getAll('topics'),avatar_media_id:profileDraft?.data?.avatar_media_id||null};}
function editProfile(){if(!needAuth())return;const current=state.me.profile;if(!profileDraft){let pending=null;try{pending=store('profile_edit');}catch{}if(!pending?.p_data||!Number.isInteger(pending.p_expected_version))pending=null;profileDraft={data:pending?.p_data||{handle:current.handle||'',display_name:current.version?current.display_name:'',bio:current.bio||'',city:current.city||'',country:current.country||'',interests:current.interests||[],avatar_media_id:current.avatar_media_id||null},version:pending?.p_expected_version??current.version??0,pending,file:null,busy:false};}
 const p=profileDraft.data,locked=!!profileDraft.pending||profileDraft.busy;open('Your public identity',`<form data-profile-form><p class="ag-note">You choose what people see. These details are public.</p><div data-avatar-preview>${profileDraft.file?`<img class="ag-profile-preview" src="${esc(profileDraft.file.preview)}" alt="Selected profile photo preview">`:p.avatar_media_id&&current.avatar_media_id===p.avatar_media_id?avatar(current,false):'<p class="ag-note">'+(p.avatar_media_id?'Uploaded profile photo ready to save.':'Your initials appear until you choose a photo.')+'</p>'}</div><label>Profile photo<input type="file" data-avatar-select accept="image/jpeg,image/png,image/webp" ${locked?'disabled':''}></label><p class="ag-note">JPEG, PNG or WebP · up to 8 MB. Your photo becomes public when you save.</p>${p.avatar_media_id||profileDraft.file?'<button type="button" class="ag-subtle" data-remove-avatar>Remove photo</button>':''}<label>Display name<input name="display_name" maxlength="80" value="${esc(p.display_name)}" required></label><label>Handle<input name="handle" pattern="[a-z0-9_]{3,30}" minlength="3" maxlength="30" value="${esc(p.handle)}" required></label><label>About you<textarea name="bio" maxlength="400">${esc(p.bio)}</textarea></label><label>City · optional<input name="city" maxlength="120" value="${esc(p.city)}"></label><label>Country · optional<input name="country" maxlength="120" value="${esc(p.country)}"></label><h3>Public interests</h3>${topicChecks(p.interests)}<button class="ag-primary" type="submit">${profileDraft.pending?'Retry the same profile edit':'Save public profile'}</button></form>${profileDraft.pending?'<button class="ag-subtle" data-discard-profile-edit>Discard pending edit and reload current profile</button>':''}<p role="status" data-form-status>${profileDraft.pending?'An earlier edit is awaiting confirmation. Retry sends exactly the same values. Discarding its local retry does not undo an edit already saved.':''}</p>`);if(locked)dialog.querySelectorAll('[data-profile-form] input,[data-profile-form] textarea,[data-profile-form] button:not([type=submit])').forEach(n=>n.disabled=true);}
function compose(intent){if(!needAuth())return;if(!draft.pending&&!draft.busy)draft.intent=intent||draft.intent;open(draft.intent==='question'?'Ask the diaspora':'Share your world',`<form data-publish><p class="ag-note">Public · Share with Greeks everywhere</p><label>Your story<textarea name="body" maxlength="1000" required placeholder="A moment, a thought, a question…" ${draft.pending||draft.busy?'readonly':''}>${esc(draft.body)}</textarea></label><label>Post type<select name="intent" ${draft.pending||draft.busy?'disabled':''}>${['moment','question','recommendation','event'].map(v=>`<option ${v===draft.intent?'selected':''}>${v}</option>`).join('')}</select></label><details><summary>Choose up to five topics</summary>${topicChecks(draft.topics)}</details><label class="ag-note">Photos or video<input type="file" data-media-select accept="image/jpeg,image/png,image/webp,video/mp4" multiple ${draft.pending||draft.busy?'disabled':''}></label><p class="ag-note">Up to 4 photos (8 MB each) or one H.264 MP4 video (32 MB, 2 minutes).</p><div data-media-previews></div><button class="ag-primary">${draft.pending?'Retry the same publication':'Publish'}</button></form><p role="status" data-form-status></p>`);renderPreviews();if(draft.pending||draft.busy)dialog.querySelectorAll('input,select,textarea').forEach(n=>n.disabled=true);}
function renderPreviews(){const target=dialog.querySelector('[data-media-previews]');if(!target)return;target.innerHTML=draft.files.map((m,i)=>`<div class="ag-upload-preview">${m.file.type.startsWith('video/')?`<video src="${esc(m.preview)}" controls playsinline preload="metadata"></video>`:`<img src="${esc(m.preview)}" alt="Selected photo preview">`}<label>Describe this for people who cannot see it<input data-media-alt="${i}" maxlength="500" value="${esc(m.alt)}" ${draft.pending||draft.busy?'disabled':''}></label><button type="button" class="ag-subtle" data-remove-media="${i}" ${draft.pending||draft.busy?'disabled':''}>Remove</button></div>`).join('');}
root.addEventListener('input',event=>{const form=event.target.closest('[data-profile-form]');if(form&&profileDraft&&!profileDraft.pending&&!profileDraft.busy)profileDraft.data=profileValues(form);});
root.addEventListener('change',event=>{if(!event.target.hasAttribute('data-avatar-select')||!profileDraft||profileDraft.pending||profileDraft.busy)return;const file=event.target.files?.[0];if(!file)return;try{mediaMetadata(file.type,file.size,'avatar');if(profileDraft.file)URL.revokeObjectURL(profileDraft.file.preview);profileDraft.file={file,request:crypto.randomUUID(),asset:null,preview:URL.createObjectURL(file)};editProfile();}catch{dialog.querySelector('[data-form-status]').textContent='Choose a JPEG, PNG or WebP photo up to 8 MB.';event.target.value='';}});
root.addEventListener('input',event=>{const f=event.target.closest('[data-publish]');if(!f||draft.pending||draft.busy)return;const data=new FormData(f);draft.body=String(data.get('body'));draft.intent=String(data.get('intent'));draft.topics=data.getAll('topics');if(event.target.hasAttribute('data-media-alt'))draft.files[Number(event.target.dataset.mediaAlt)].alt=event.target.value;});
root.addEventListener('change',event=>{if(!event.target.hasAttribute('data-media-select')||draft.pending||draft.busy)return;try{const files=[...event.target.files];files.forEach(f=>mediaMetadata(f.type,f.size));const combined=[...draft.files.map(x=>x.file),...files],videos=combined.filter(f=>f.type==='video/mp4').length;if(combined.length>4||videos&&(videos!==1||combined.length!==1))throw Error('Choose up to four photos or one video.');for(const file of files)draft.files.push({file,request:crypto.randomUUID(),asset:null,preview:URL.createObjectURL(file),alt:''});renderPreviews();}catch{dialog.querySelector('[data-form-status]').textContent='Choose up to four JPEG, PNG or WebP photos (8 MB each), or one H.264 MP4 video (32 MB, 2 minutes).';}event.target.value='';});

function notificationCard(n){const labels={follow:'started following you',like:'liked your post',comment:'replied to your post',accepted_answer:'chose your answer as useful'};return `<button class="ag-notification" data-notification="${esc(n.id)}" data-notify-post="${esc(n.post_id||'')}" data-notify-profile="${esc(n.actor?.id)}" data-unread="${!n.read_at}"><b>${esc(n.actor?.display_name||'Community member')}</b> ${labels[n.kind]||'interacted with you'}<small>${esc(age(n.created_at))}${!n.read_at?' · Unread':''}</small></button>`;}
async function notifications(more=false){if(!needAuth())return;const version=more?dialogVersion:open('Your notifications','<p>Loading…</p>');if(!more)notificationView={ids:new Set(),next:0};const r=await rpc('community_notifications',{p_limit:30,p_offset:more?notificationView.next:0});if(version!==dialogVersion)return;if(!Array.isArray(r.notifications))throw Error('notifications_unconfirmed');if(!more)$('[data-dialog-body]').innerHTML='<div data-notification-list></div><button class="ag-subtle" data-more-notifications>More notifications</button><p role="status" data-form-status></p>';const fresh=r.notifications.filter(n=>!notificationView.ids.has(n.id));fresh.forEach(n=>notificationView.ids.add(n.id));dialog.querySelector('[data-notification-list]').insertAdjacentHTML('beforeend',fresh.map(notificationCard).join(''));if(!notificationView.ids.size)dialog.querySelector('[data-notification-list]').innerHTML='<p>No notifications yet. New follows and conversations will appear here.</p>';notificationView.next=r.next_offset;dialog.querySelector('[data-more-notifications]').hidden=r.next_offset==null;}
async function openPost(id){if(!UUID.test(id||''))return;const generation=++state.generation;state.postView=id;const r=await rpc('community_post_get',{p_post:id},'prefer');if(generation!==state.generation)return;close();state.posts=r.post?[r.post]:[];state.next=null;renderFeed();if(!r.post)status('This post is not available.');}
root.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-close'))return close();
 if(b.hasAttribute('data-remove-media')&&!draft.pending&&!draft.busy){const [m]=draft.files.splice(Number(b.dataset.removeMedia),1);if(m){URL.revokeObjectURL(m.preview);if(m.asset)action('discard-media',async()=>{const scope=await accountReady();await C.auth.ensureFresh();checkScope(scope);await discardCommunityMedia({base:C.BASE,apikey:C.KEY,token:C.auth.token(),assetId:m.asset.id});});}return renderPreviews();}
 if(b.dataset.mode)return switchMode(b.dataset.mode);
 if(b.hasAttribute('data-topic')){state.topic=b.dataset.topic||null;root.querySelectorAll('[data-topic]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));return loadFeed();}
 if(b.hasAttribute('data-account'))return needAuth()?(state.me?.profile?.handle?action('profile',()=>showProfile(state.me.profile.id)):editProfile()):null;
 if(b.hasAttribute('data-remove-avatar')&&profileDraft&&!profileDraft.pending&&!profileDraft.busy){if(profileDraft.file)URL.revokeObjectURL(profileDraft.file.preview);profileDraft.file=null;profileDraft.data.avatar_media_id=null;return editProfile();}
 if(b.hasAttribute('data-discard-profile-edit'))return action('discard-profile',async()=>{await loadMe();store('profile_edit',null);if(profileDraft?.file)URL.revokeObjectURL(profileDraft.file.preview);profileDraft=null;editProfile();});
 if(b.hasAttribute('data-edit-profile'))return editProfile();
 if(b.hasAttribute('data-preferences'))return preferences();
 if(b.hasAttribute('data-compose'))return compose(b.dataset.compose);
 if(b.hasAttribute('data-retry'))return loadFeed();
 if(b.hasAttribute('data-more'))return !state.loading&&loadFeed(true);
 if(b.dataset.profile)return action('profile',()=>showProfile(b.dataset.profile));
 if(b.dataset.profileFeed){state.postView=null;state.mode='profile';state.profile=b.dataset.profileFeed;close();return loadFeed();}
 if(b.dataset.comments)return action('comments',()=>comments(b.dataset.comments));
 if(b.dataset.photo){const p=state.posts.find(p=>p.id===b.dataset.photo),m=mediaItems(p?.media)[Number(b.dataset.index)];if(m)open('Photo',`<img src="${esc(safeUrl(m.url))}" alt="${esc(m.alt||'Community photo')}">`);return;}
 if(b.dataset.like||b.dataset.save){if(!needAuth())return;const id=b.dataset.like||b.dataset.save,p=state.posts.find(p=>p.id===id),like=!!b.dataset.like;if(!p)return;action((like?'like:':'save:')+id,async()=>{const desired=like?!p.liked:!p.saved,r=await rpc(like?'community_like_set':'community_saved_set',{p_post:id,[like?'p_liked':'p_saved']:desired});if(r.post_id!==id||r[like?'liked':'saved']!==desired)throw Error('unconfirmed');if(like){p.liked=r.liked;p.likes=r.likes;}else p.saved=r.saved;const card=root.querySelector(`[data-post="${id}"]`);if(card)card.outerHTML=postCard(p);observeVideo();});return;}
 if(b.dataset.share)return action('share',async()=>{const url=location.origin+'/community/?post='+b.dataset.share;if(navigator.share)await navigator.share({title:'A conversation on Zoi',url});else{await navigator.clipboard.writeText(url);status('Post link copied.');}});
 if(b.dataset.follow){if(!needAuth())return;return action('follow',async()=>{const desired=b.dataset.following!=='true';const r=await rpc('community_follow_set',{p_profile:b.dataset.follow,p_follow:desired});if(r.profile_id!==b.dataset.follow||r.following!==desired)throw Error('unconfirmed');b.dataset.following=String(r.following);b.textContent=r.following?'Following · unfollow':'Follow';await loadMe();});}
 if(b.dataset.block||b.dataset.mute||b.dataset.unblock||b.dataset.unmute){if(!needAuth())return;const blocked=!!(b.dataset.block||b.dataset.unblock),id=b.dataset.block||b.dataset.mute||b.dataset.unblock||b.dataset.unmute,desired=!!(b.dataset.block||b.dataset.mute);return action('privacy',async()=>{const r=await rpc(blocked?'community_block_set':'community_mute_set',{p_profile:id,[blocked?'p_blocked':'p_muted']:desired});if(r.profile_id!==id||r[blocked?'blocked':'muted']!==desired)throw Error('unconfirmed');close();await loadMe();await loadFeed();status(desired?(blocked?'Account blocked in your signed-in experience. Public posts remain accessible on the internet.':'Account muted.'):'Account preference updated.');});}
 if(b.dataset.accept){const p=state.posts.find(p=>p.id===b.dataset.question);return action('answer',async()=>{const chosen=p.accepted_comment_id===b.dataset.accept?null:b.dataset.accept;const r=await rpc('community_accept_answer',{p_post:p.id,p_comment:chosen,p_expected_version:p.context_version});if(r.post_id!==p.id||r.accepted_comment_id!==chosen||r.context_version!==p.context_version+1)throw Error('unconfirmed');p.accepted_comment_id=r.accepted_comment_id;p.context_version=r.context_version;await comments(p.id);renderFeed();});}
 if(b.dataset.postMenu){const p=state.posts.find(p=>p.id===b.dataset.postMenu);open('Post options',`<button class="ag-menu-action" data-share="${p.id}">Share this conversation</button>${p.mine?`<button class="ag-menu-action" data-delete-post="${p.id}">Delete my post</button>`:''}${!p.mine?`<button class="ag-menu-action" data-report="${p.id}">Report a problem</button><button class="ag-menu-action" data-mute="${p.author.id}">Mute this account</button><button class="ag-menu-action" data-block="${p.author.id}">Block this account</button>`:''}`);return;}
 if(b.dataset.deletePost){const post=state.posts.find(p=>p.id===b.dataset.deletePost);if(!post?.mine||!needAuth())return;open('Delete your post',`<p>This removes your post and its conversation. Other people may already have seen or copied it.</p><button class="ag-primary" data-confirm-delete="${post.id}">Delete this post</button><button class="ag-subtle" data-close>Keep post</button><p role="status" data-form-status></p>`);return;}
 if(b.dataset.confirmDelete)return action('delete',async()=>{const scope=await accountReady(),id=b.dataset.confirmDelete;const deleted=await C.api.rpc('feed_delete',{p_id:id},{auth:'require'});checkScope(scope);if(deleted!==true){const current=await rpc('community_post_get',{p_post:id});if(current.post!==null)throw Error('unconfirmed');}state.postView=null;close();await loadFeed();status('Your post is no longer available.');});
 if(b.dataset.report){if(!needAuth())return;let pending;try{pending=store('report_'+b.dataset.report);}catch{}if(!UUID.test(pending?.p_request||'')||pending.p_post!==b.dataset.report)pending=null;open('Report this post',`<form data-report-form="${b.dataset.report}" data-request="${pending?.p_request||crypto.randomUUID()}"><label>Reason<select name="reason">${['spam','scam','harassment','hate','privacy','other'].map(v=>`<option ${pending?.p_reason===v?'selected':''}>${v}</option>`).join('')}</select></label><label>What should the moderation team know?<textarea name="details" maxlength="1000">${esc(pending?.p_details||'')}</textarea></label><button class="ag-primary">${pending?'Retry same report':'Submit report'}</button></form><p role="status" data-form-status>${pending?'The same report is awaiting confirmation.':''}</p>`);if(pending)dialog.querySelectorAll('select,textarea').forEach(n=>n.disabled=true);return;}
 if(b.hasAttribute('data-more-notifications'))return action('more-notifications',()=>notifications(true));
 if(b.hasAttribute('data-notifications'))return action('notifications',notifications);
 if(b.dataset.notification)return action('notification',async()=>{const receipt=await rpc('community_notifications_read',{p_ids:[b.dataset.notification]});if(!Number.isInteger(receipt.updated)||!Number.isInteger(receipt.unread_count))throw Error('unconfirmed');if(b.dataset.notifyPost)await openPost(b.dataset.notifyPost);else await showProfile(b.dataset.notifyProfile);});
 if(b.dataset.moreComments)return action('more-replies',async()=>{const version=dialogVersion,post=state.posts.find(p=>p.id===b.dataset.moreComments);b.disabled=true;try{const r=await rpc('community_comments',{p_post:b.dataset.moreComments,p_offset:Number(b.dataset.offset)},'prefer');if(version!==dialogVersion)return;const target=dialog.querySelector('[data-replies]');if(!Array.isArray(r.comments))throw Error('comments_unconfirmed');target.insertAdjacentHTML('beforeend',r.comments.filter(c=>!target.querySelector(`[data-reply-id="${c.id}"]`)).map(c=>replyCard(c,post)).join(''));if(r.next_offset==null)b.remove();else b.dataset.offset=r.next_offset;}finally{b.disabled=false;}});

});
root.addEventListener('submit',event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const f=new FormData(form);if(form.hasAttribute('data-search')){state.query=String(f.get('query')).trim();return loadFeed();}
 action('form',async()=>{
 if(form.hasAttribute('data-signin')){const email=String(f.get('email')).trim();await C.otp.send(email);open('Check your email',`<form data-verify data-email="${esc(email)}"><label>Sign-in code<input name="code" inputmode="numeric" pattern="[0-9]{6,8}" autocomplete="one-time-code" required></label><button class="ag-primary">Sign in</button></form><p role="status" data-form-status></p>`);}
 else if(form.hasAttribute('data-verify')){await C.otp.verify(form.dataset.email,String(f.get('code')).trim());close();await loadMe();await loadFeed();}
 else if(form.hasAttribute('data-preferences-form')){await rpc('community_preferences_save',{p_expected_version:state.me?.preferences?.version||0,p_data:{topics:f.getAll('topics'),city:f.get('city'),country:f.get('country'),locality_enabled:f.has('locality')}});await loadMe();close();await loadFeed();}
 else if(form.hasAttribute('data-profile-form')){
  if(!needAuth())return;const scope=await accountReady(),working=profileDraft;if(working.busy)return;if(!working.pending){working.data=profileValues(form);if(working.data.interests.length>8)throw Error('choose_eight_topics');}working.busy=true;form.querySelectorAll('input,textarea,button').forEach(n=>n.disabled=true);const message=dialog.querySelector('[data-form-status]');
  try{
   if(!working.pending){const data=structuredClone(working.data);if(working.file&&!working.file.asset){message.textContent='Uploading profile photo…';if(!(await C.auth.ensureFresh()))throw Error('sign_in_required');checkScope(scope);working.file.asset=await uploadCommunityMedia({base:C.BASE,apikey:C.KEY,token:C.auth.token(),file:working.file.file,requestId:working.file.request,purpose:'avatar'});checkScope(scope);}if(working.file)data.avatar_media_id=working.file.asset.id;data.handle=data.handle.trim();data.display_name=data.display_name.trim();data.bio=data.bio.trim();data.city=data.city.trim();data.country=data.country.trim();const payload={p_expected_version:working.version,p_data:data};store('profile_edit',payload);working.pending=payload;working.data=data;}
   checkScope(scope);message.textContent='Saving your public profile…';const payload=working.pending;let saved;
   try{const r=await rpc('community_profile_save',payload);saved=r.profile;}catch(error){checkScope(scope);const current=await rpc('community_me');if(profileMatches(current.profile,payload.p_data,payload.p_expected_version+1))saved=current.profile;else throw error;}
   checkScope(scope);if(saved?.id!==state.me.profile.id||!profileMatches(saved,payload.p_data,payload.p_expected_version+1))throw Error('profile_unconfirmed');state.me.profile=saved;store('profile_edit',null);if(working.file)URL.revokeObjectURL(working.file.preview);profileDraft=null;$('[data-account]').textContent='Your profile';$('[data-own-avatar]').innerHTML=avatar(saved,false);close();await loadFeed();status('Your public profile is saved.');
  }finally{working.busy=false;if(profileDraft===working&&dialog.querySelector('[data-profile-form]')){dialog.querySelectorAll('[data-profile-form] input,[data-profile-form] textarea,[data-profile-form] button').forEach(n=>n.disabled=!!working.pending&&n.type!=='submit');dialog.querySelector('[data-profile-form] .ag-primary').textContent=working.pending?'Retry the same profile edit':'Save public profile';}}
 }
 else if(form.hasAttribute('data-publish')){
  if(!needAuth())return;const scope=await accountReady(),working=draft,message=dialog.querySelector('[data-form-status]');if(working.busy)return;working.busy=true;
  const controls=[...form.querySelectorAll('input,button,textarea,select')];controls.forEach(n=>n.disabled=true);
  try{
   if(!working.pending){
    const snapshot={body:working.body.trim(),intent:working.intent,topics:[...working.topics],files:working.files.map(m=>({...m}))};
    if(!snapshot.body||snapshot.body.length>1000)throw Error('post_body_required');if(snapshot.topics.length>5)throw Error('choose_five_topics');
    if(!(await C.auth.ensureFresh()))throw Error('sign_in_required');checkScope(scope);const token=C.auth.token();
    for(let i=0;i<snapshot.files.length;i++){const media=snapshot.files[i];if(!media.asset){message.textContent=`Uploading ${i+1} of ${snapshot.files.length}…`;const asset=await uploadCommunityMedia({base:C.BASE,apikey:C.KEY,token,file:media.file,requestId:media.request});checkScope(scope);media.asset=asset;working.files[i].asset=asset;}}
    const pending={p_request:crypto.randomUUID(),p_body:snapshot.body,p_media:snapshot.files.map(m=>m.asset.id),p_listing:null,p_context:{intent:snapshot.intent,topics:snapshot.topics,city:null,country:null,media_alts:Object.fromEntries(snapshot.files.map(m=>[m.asset.id,m.alt]))}};
    storePending(pending);working.pending=pending;
   }
   checkScope(scope);message.textContent='Publishing…';const payload=working.pending,r=await rpc('community_publish',payload);checkScope(scope);
   if(r.request_id!==payload.p_request||!UUID.test(r.id||''))throw Error('unconfirmed');
   // A verified publication is final even if the following feed read fails.
   try{storePending(null);}catch{status('Published. Your browser could not clear the draft; if it reappears, retrying it won’t publish a duplicate.');}
   working.files.forEach(m=>URL.revokeObjectURL(m.preview));draft={body:'',intent:'moment',topics:[],files:[],pending:null,busy:false};close();
   try{await openPost(r.id);status('Your post is published.');}catch{status('Your post is published. The feed could not refresh; use Retry feed to view it.');$('[data-feed]').innerHTML='<button class="ag-primary" data-retry>Retry feed</button>';}
  }finally{working.busy=false;if(draft===working&&dialog.querySelector('[data-publish]')){const current=dialog.querySelector('[data-publish]');current.querySelectorAll('input,button,textarea,select').forEach(n=>n.disabled=!!working.pending&&n.type!=='submit');current.querySelector('button.ag-primary').textContent=working.pending?'Retry the same publication':'Publish';}}
 }
 else if(form.dataset.comment){
  if(!needAuth())return;const scope=await accountReady(),id=form.dataset.comment;let payload=pendingReply(id);if(!payload){payload={p_post:id,p_request:crypto.randomUUID(),p_body:String(f.get('body')).trim()};if(!payload.p_body||payload.p_body.length>500)throw Error('reply_body_required');store('reply_'+id,payload);}
  const message=dialog.querySelector('[data-form-status]');form.querySelector('textarea').readOnly=true;form.querySelector('button').disabled=true;
  try{const r=await rpc('community_comment',payload);checkScope(scope);if(!UUID.test(r.comment?.id||'')||r.comment.post_id!==id||r.comment.body!==payload.p_body||r.comment.author?.id!==state.me.profile.id)throw Error('unconfirmed');store('reply_'+id,null);form.reset();message.textContent='Your reply is posted.';const post=state.posts.find(p=>p.id===id);if(post&&!dialog.querySelector(`[data-reply-id="${r.comment.id}"]`)){post.comments=(Number(post.comments)||0)+1;dialog.querySelector('[data-replies]').insertAdjacentHTML('beforeend',replyCard(r.comment,post));renderFeed();}form.querySelector('textarea').readOnly=false;}
  finally{form.querySelector('button').disabled=false;form.querySelector('button').textContent=pendingReply(id)?'Retry the same reply':'Reply';}
 }
 else if(form.dataset.reportForm){if(!needAuth())return;const id=form.dataset.reportForm;let payload=store('report_'+id);if(!payload){payload={p_post:id,p_reason:f.get('reason'),p_details:f.get('details'),p_request:form.dataset.request};store('report_'+id,payload);}form.querySelectorAll('select,textarea').forEach(n=>n.disabled=true);const r=await rpc('community_report',payload);if(r.status!=='pending'||!UUID.test(r.report_id||''))throw Error('unconfirmed');store('report_'+id,null);open('Report received','<p>Your report is pending review. This does not automatically remove the post.</p>');}

 });
});
document.addEventListener('visibilitychange',()=>{if(document.hidden)root.querySelectorAll('video').forEach(v=>v.pause());});
dialog.addEventListener('close',()=>{dialogVersion++;dialog.querySelectorAll('video').forEach(v=>v.pause());});
window.addEventListener('storage',event=>{if(event.key===C.keys.auth){checkAccount();loadMe().then(()=>loadFeed()).catch(()=>status('Your session changed. Refresh to continue.'));}});
window.addEventListener('focus',()=>{if(checkAccount())loadMe().then(()=>loadFeed()).catch(()=>status('Your account could not be loaded.'));});
async function discover(){try{const r=await C.api.rpc('explore_search',{p_q:'',p_type:'business',p_city:null,p_country:null,p_limit:3,p_offset:0},{auth:'anon'});if(!Array.isArray(r))return;const rows=r.filter(x=>x.slug);if(rows.length)$('[data-discovery]').innerHTML='<h2>Discover Greek businesses</h2>'+rows.map(x=>`<a class="ag-discover" href="/business/${encodeURIComponent(x.slug)}">${safeUrl(x.photo_url)?`<img src="${esc(safeUrl(x.photo_url))}" alt="" loading="lazy" referrerpolicy="no-referrer">`:avatar({display_name:x.name},false)}<span><b>${esc(x.name)}</b><small>${esc([x.city,x.country].filter(Boolean).join(' · '))}</small></span></a>`).join('')+'<a class="ag-note" href="/explore/">Explore all →</a>';}catch{}}
(async()=>{try{await loadMe();}catch{status('Your account could not be loaded. Refresh before making changes.');}const post=new URLSearchParams(location.search).get('post');if(UUID.test(post||''))await action('post',()=>openPost(post));else await loadFeed();discover();if(new URLSearchParams(location.search).get('moderation')==='reports'&&needAuth())await action('moderation',()=>moderation());})();

if(window.ZoiOrthocal){const r=dailyRitual(window.ZoiOrthocal);$('[data-ritual]').innerHTML='<h2>A little Greece, every day</h2><p class="ag-note">'+esc(r.date)+' · Athens</p><h3 lang="el">'+esc(r.word[0])+'</h3><p>'+esc(r.word[1])+' · '+esc(r.word[2])+'</p>'+(r.namedays.length?'<p>Today’s namedays: '+esc(r.namedays.join(', '))+'</p>':'')+(r.feasts.length?'<p>'+esc(r.feasts.map(f=>f.name).join(' · '))+'</p>':r.next?'<p>Next feast: '+esc(r.next.name)+' · '+esc(r.next.date)+'</p>':'')+'<p class="ag-note">Orthodox calendar reference · local parish calendars can differ.</p>'; }

root.addEventListener('error',event=>{const media=event.target;if(!(media instanceof HTMLMediaElement||media instanceof HTMLImageElement)||!media.closest('.ag-media')||media.dataset.failed)return;media.dataset.failed='true';const note=document.createElement('div');note.className='ag-media-failure';note.setAttribute('role','status');note.textContent='This media could not load. ';const retry=document.createElement('button');retry.className='ag-subtle';retry.textContent='Retry media';retry.addEventListener('click',()=>{note.remove();delete media.dataset.failed;if(media instanceof HTMLMediaElement)media.load();else{const src=media.src;media.removeAttribute('src');media.src=src;}});note.append(retry);media.closest('.ag-media').append(note);},true);

async function moderation(offset=0){const version=open('Community moderation','<p>Checking platform moderator access…</p><p role="status" data-form-status></p>');const r=await rpc('community_reports_queue',{p_limit:30,p_offset:offset});if(version!==dialogVersion)return;if(!Array.isArray(r.reports))throw Error('unconfirmed');$('[data-dialog-body]').innerHTML='<p class="ag-note">Restricted to authorized platform moderators. Review captured content and the report before deciding.</p>'+r.reports.map(report=>`<article class="ag-reply-body"><h3>${esc(report.reason)}</h3><p>${esc(report.details)}</p><blockquote>${esc(report.content_snapshot?.body||'Captured post is unavailable')}</blockquote><form data-moderation-review="${esc(report.id)}"><label>Decision<select name="action"><option value="dismiss">Dismiss report</option><option value="hide">Hide post</option></select></label><label>Review note<textarea name="note" required maxlength="1000"></textarea></label><button class="ag-primary">Record decision</button></form></article>`).join('')+(r.reports.length?'':'<p>No pending reports on this page.</p>')+(offset?`<button class="ag-subtle" data-report-page="${Math.max(0,offset-30)}">Previous reports</button>`:'')+(r.reports.length===30&&offset<990?`<button class="ag-subtle" data-report-page="${offset+30}">More reports</button>`:'')+'<p role="status" data-form-status></p>';}
root.addEventListener('click',event=>{const b=event.target.closest('[data-report-page]');if(b)action('moderation',()=>moderation(Number(b.dataset.reportPage)));});
root.addEventListener('submit',event=>{const form=event.target;if(!form.matches('[data-moderation-review]'))return;event.preventDefault();action('moderation-review',async()=>{const f=new FormData(form),key='review_'+form.dataset.moderationReview;let payload=store(key);if(!payload){payload={p_report:form.dataset.moderationReview,p_action:f.get('action'),p_note:String(f.get('note')).trim()};if(!payload.p_note)throw Error('review_note_required');store(key,payload);}form.querySelectorAll('input,select,textarea,button').forEach(n=>n.disabled=true);try{const r=await rpc('community_reports_review',payload);if(r.report_id!==payload.p_report||r.status!==(payload.p_action==='hide'?'hidden':'dismissed'))throw Error('unconfirmed');store(key,null);await moderation();}finally{form.querySelector('button').disabled=false;form.querySelector('button').textContent='Retry same decision';}});});

mountMusic(root);
